mapper.insert:
        INSERT INTO cvpl (
                           cvpl_no
                         , cvpl_ty_cd
                         , cvpl_loc
                         , cvpl_cn
                         , cvpl_stts_cd
                         , cvpl_reg_dt
                         , cvpl_mdf_dt
                         , cvpl_ttl
                         , user_no
                         , ho_no
                         , apt_cmplex_no
        ) VALUES (
                   'CV' || TO_CHAR(SYSDATE, 'YYMMDDHH24MISS')
                     /* 문의번호: 임시 방식. 같은 초에 2건 등록되면 중복 가능성이 있으므로 실무에서는 SEQUENCE 권장 */
                 , #{cvplTyCd}
                 , '미지정'
                 , #{cvplCn}
                 , '접수'
                 , SYSDATE
                 , SYSDATE
                 , #{cvplTtl}
                 , #{userNo}
                 , #{hoNo}
                 , #{aptCmplexNo}
                 )

mapper.delete:
        DELETE FROM cvpl
        WHERE cvpl_no = #{cvplNo}
          AND user_no = #{userNo}

mapper.select:
        SELECT COUNT(*)
        FROM cvpl
        WHERE user_no = #{userNo}
